  { id: 'cutter', key: '5', name: 'Glass cutter', cost: 40, max: 4, blurb: 'Open one display case without a sound.', reach: 0 },
];

export const SMOKE_SECONDS = 7;
export const SMOKE_RADIUS = 58;

export function toolById(id) {
